package com.bheemnagartimes.news.service;
import com.bheemnagartimes.news.model.NewsArticle;import org.springframework.stereotype.Service;import java.util.regex.Pattern;
@Service public class ArticleGeneratorService{public NewsArticle generate(String raw,String date,String location,String section){String text=raw.trim().replace("\r","");NewsArticle a=new NewsArticle();a.setSection(section==null||section.isBlank()?detectSection(text):section);a.setHeadline(headline(text));String first=text.split("(?<=[।!?])\\s+")[0];a.setSubheadline(first.length()>110?first.substring(0,110)+"…":first);a.setStrapline("मुख्य घटनाक्रम, संबंधित पक्षों की प्रतिक्रिया और आगे की प्रक्रिया पर नजर");a.setDateline((location==null||location.isBlank()?"भीमनगर":location)+", "+(date==null||date.isBlank()?"22 सितंबर 2026":date)+" |");a.setBody(paragraphs(text));a.setSecondaryHeading("मामले की मुख्य बातें");a.setSecondaryBody("उपलब्ध जानकारी के अनुसार संबंधित विभाग और पक्ष मामले पर आगे की प्रक्रिया तय करेंगे। आधिकारिक आदेश या अंतिम निर्णय आने पर जानकारी अपडेट की जाएगी।");a.setSidebarHeading("त्वरित दृष्टि");a.setSidebarBody("अंतिम प्रकाशन से पहले नाम, तारीख, आंकड़े और आधिकारिक स्रोतों का सत्यापन करें।");String q=quote(text);a.setQuote(q);a.setQuoteAttribution(q.isBlank()?"":"स्रोत में दर्ज कथन");return a;}private String headline(String t){if(has(t,"cctv","सीसीटीवी","कैमरा"))return"मेडिकल स्टोर पर सीसीटीवी लगाने की तैयारी?";if(has(t,"skill","स्किल","कौशल"))return"युवाओं के लिए हुनर दिखाने का बड़ा मौका";if(has(t,"सड़क","हाईवे","एनएच"))return"सड़क से जुड़े प्रस्ताव पर बढ़ी निगरानी";if(has(t,"बिजली","विद्युत"))return"बिजली व्यवस्था को लेकर प्रशासन से उम्मीदें बढ़ीं";String s=t.replaceAll("[\\r\\n]+"," ").trim();return s.length()>80?s.substring(0,80)+"…":s;}private boolean has(String t,String...xs){String l=t.toLowerCase();for(String x:xs)if(l.contains(x.toLowerCase()))return true;return false;}private String detectSection(String t){if(has(t,"सरकार","मंत्रालय","प्रस्ताव","नियम"))return"जनहित में बड़ा फैसला";if(has(t,"युवा","स्किल","कौशल","प्रतियोगिता"))return"युवा अवसर";if(has(t,"स्वास्थ्य","अस्पताल","दवा","मेडिकल"))return"स्वास्थ्य";return"स्थानीय समाचार";}private String paragraphs(String t){String n=t.replaceAll("\\n{3,}","\\n\\n").trim();if(n.contains("\\n\\n"))return n;String[] s=n.split("(?<=[।!?])\\s+");StringBuilder b=new StringBuilder();int c=0;for(String x:s){if(x.isBlank())continue;if(b.length()>0)b.append("\\n\\n");b.append(x.trim());if(++c>=5)break;}return b.toString();}private String quote(String t){var m=Pattern.compile("[“\\\"]([^”\\\"]{20,220})[”\\\"]").matcher(t);return m.find()?m.group(1):"";}}